const firstItem = $input.first()?.json || {};
const body = firstItem.body || firstItem;
const events = body?.events || [];

if (!events || events.length === 0) {
  return [{ json: { message: "Webhook verify ok" } }];
}

// ⚠️ 管理員 LINE User ID 設定（可填入一個或多個 User ID，或使用環境變數 $env.ADMIN_USER_ID）
const ADMIN_USER_IDS = [
  'Ud303b043ce776a7b734ff950f91c6612', // 請將此處替換為你的 LINE User ID (例如: U1234567890abcdef...)
  $env.ADMIN_USER_ID   // 若 n8n 環境變數有設定 ADMIN_USER_ID 也會自動生效
].filter(Boolean);

const results = [];
const urlRegex = /(https?:\/\/[^\s]+)/i;

// 管理指令
const apiTestRegex = /^(測試api|測試gemini|\/checkapi)$/i;
const listModelsRegex = /^(列出模型|查詢模型|\/models)$/i;
const setModelRegex = /^\/setmodel\s+(.+)$/i;
const testModelRegex = /^\/testmodel\s+(\S+)$/i;

for (const event of events) {
  if (event.type === 'message') {
    const groupId = event.source?.groupId || event.source?.roomId || event.source?.userId;
    const userId = event.source?.userId;

    // 驗證當前發送者是否為管理員
    const isAdmin = ADMIN_USER_IDS.includes(userId);

    if (event.message?.type === 'text') {
      const text = (event.message.text || '').trim();

      // ----------------------------------------------------
      // 🔒 管理員專屬指令區 (非管理員會直接跳過此區塊)
      // ----------------------------------------------------
      if (isAdmin) {
        // 指令一：測試 API
        if (apiTestRegex.test(text)) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'api_test',
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令二：列出模型
        if (listModelsRegex.test(text)) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'list_models',
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令三：設定模型
        const setModelMatch = text.match(setModelRegex);
        if (setModelMatch) {
          const parts = setModelMatch[1].trim().split(/\s+/);
          const targetKey = parts.length >= 2 ? parts[0].toLowerCase() : 'main';
          const newModel = parts.length >= 2 ? parts[1].trim() : parts[0].trim();

          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'set_model',
              targetKey: targetKey,
              newModel: newModel,
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令四：測試模型
        const testModelMatch = text.match(testModelRegex);
        if (testModelMatch) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'test_model',
              targetModel: testModelMatch[1].trim(),
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }
      }

      // ----------------------------------------------------
      // 💬 一般對話與網址解析區
      // ----------------------------------------------------
      const urlMatch = text.match(urlRegex);
      if (urlMatch) {
        results.push({
          json: {
            replyToken: event.replyToken,
            groupId: groupId,
            userId: userId,
            userMessage: text,
            url: urlMatch[1],
            messageType: 'url',
            isTriggered: false,
            timestamp: event.timestamp
          }
        });
      } else {
        const isSummaryReq = /統整|摘要|總結/i.test(text);
        const triggerRegex = /[@＠]bot|我要吃香腸|幽默大師|講一個笑話|吃啥|作詩|出來面對/i;

        results.push({
          json: {
            replyToken: event.replyToken,
            groupId: groupId,
            userId: userId,
            userMessage: text,
            messageType: 'text',
            isTriggered: triggerRegex.test(text) || isSummaryReq,
            isSummaryReq: isSummaryReq,
            timestamp: event.timestamp
          }
        });
      }

    } else if (event.message?.type === 'image') {
      results.push({
        json: {
          replyToken: event.replyToken,
          groupId: groupId,
          userId: userId,
          messageId: event.message.id,
          messageType: 'image',
          isTriggered: false,
          timestamp: event.timestamp
        }
      });
    }
  }
}

return results.length > 0 ? results : [{ json: { status: "ignored" } }];

// 1. 取得全體團員的人設對照表（相容新舊節點名稱）
let rawImportantItems = [];
try {
  rawImportantItems = $('取得全團員人格特質').all();
} catch (e) {
  try { rawImportantItems = $('Get row(s)1').all(); } catch (err) {}
}

const personaMap = new Map(); // userId -> { id, name, info }

for (const item of rawImportantItems) {
  const userId = item.json?.userId;
  const name = item.json?.displayName || item.json?.message; 
  const info = item.json?.info;
  const id = item.json?.id;

  if (!userId || userId === 'Null' || !name || name === 'Null' || String(name).trim() === '') continue;

  const cleanInfo = (!info || info === 'Null') ? '' : String(info).trim();

  // 保留該 userId 最新的一筆紀錄
  const existing = personaMap.get(userId);
  if (!existing || id > existing.id) {
    personaMap.set(userId, { id, name: String(name).trim(), info: cleanInfo });
  }
}

const importantLines = [];
for (const [userId, data] of personaMap.entries()) {
  const infoPart = data.info ? ` [特徵/人設/暱稱: ${data.info}]` : '';
  importantLines.push(`- ${data.name}${infoPart} (ID: ${userId})`);
}
const importantHistoryText = importantLines.join('\n') || '無成員人設資料';

// 2. 取得歷史對話紀錄
let rawChatItems = [];
try {
  rawChatItems = $('Get row(s)').all();
} catch (e) {
  rawChatItems = $input.all();
}

const seenChatIds = new Set();
const chatMessages = [];

for (const item of rawChatItems) {
  const id = item.json?.id;
  if (id && seenChatIds.has(id)) continue;
  if (id) seenChatIds.add(id);

  const userId = item.json?.userId || '未知成員';
  const msg = item.json?.message || '';

  // 透過 userId 比對全團員人設表
  const persona = personaMap.get(userId);

  let displayName = userId;
  if (persona) {
    displayName = persona.name;
  } else if (userId !== '未知成員') {
    displayName = `成員(${userId.slice(-4)})`;
  }

  chatMessages.push(`[發言者: ${displayName}] (ID: ${userId})\n${msg}`);
}

const chatHistoryText = chatMessages.reverse().join('\n---\n') || '無一般歷史紀錄';

// 3. 取得當前發問者資訊
let lineEvent = {};
try {
  lineEvent = $('Parse LINE Event').item.json;
} catch (e) {
  try { lineEvent = $('LINE Webhook').item.json.body.events[0]; } catch (err) {}
}

const userLatestMsg = lineEvent.userMessage || lineEvent.message?.text || '';
const groupId = lineEvent.groupId || lineEvent.source?.groupId || '';
const currentUserId = lineEvent.userId || lineEvent.source?.userId || '';

const currentPersona = personaMap.get(currentUserId);
const currentUserName = currentPersona ? currentPersona.name : currentUserId;

// 4. 輸出 Prompt
return [{
  json: {
    prompt: `【當前發問者】：${currentUserName} (ID: ${currentUserId})
【使用者最新指令/提問】：${userLatestMsg}

【群組最近對話紀錄】：
${chatHistoryText}

【群組成員稱號與人設特徵對照】：
${importantHistoryText}

-------------------
【稱呼與人名強制規範】：
1. 名字 100% 完全精確（零錯字原則）：稱呼成員時，如果使用 displayName，必須 100% 完全複製上方「對照表」中的字形，嚴禁自作聰明替換成同音字、同音異體字或簡體字。
2. 靈活使用群組暱稱：亦可直接使用 info 欄位內提到的常見暱稱（如：吉爺、C祖），讓對話自然風趣。
3. 發言歸屬精準：標註的發言者名稱即為該句話的真正發言人，請精準辨識「誰說了什麼話」，切勿張冠李戴。`
  }
}];

const isError = $json.error !== undefined;
const origin = $('Parse LINE Event').item.json;

if (isError) {
  return [{
    json: {
      pageText: '（此網址無法正常抓取內容，可能被網站阻擋或連線逾時）',
      fetchFailed: true,
      url: origin.url,
      replyToken: origin.replyToken,
      groupId: origin.groupId,
      userId: origin.userId,
      userMessage: origin.userMessage,
      timestamp: origin.timestamp
    }
  }];
}

const html = $json.data || $json.body || String($json) || '';
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 4000);

return [{
  json: {
    pageText: text,
    fetchFailed: false,
    url: origin.url,
    replyToken: origin.replyToken,
    groupId: origin.groupId,
    userId: origin.userId,
    userMessage: origin.userMessage,
    timestamp: origin.timestamp
  }
}];

const origin = $('Parse LINE Event').item.json;
const analysis = $json.output || '（連結分析取得失敗）';

return [{
  json: {
    replyToken: origin.replyToken,
    groupId: origin.groupId,
    userId: origin.userId,
    userMessage: `[連結] ${analysis}`,
    timestamp: origin.timestamp
  }
}];

let lineEvent = {};
try {
  lineEvent = $('Parse LINE Event').item.json;
} catch (e) {
  try { lineEvent = $('LINE Webhook').item.json.body.events[0]; } catch (err) {}
}

const userMessage = lineEvent.userMessage || lineEvent.message?.text || '';
const targetUserId = lineEvent.userId || lineEvent.source?.userId || '';

// 撈取原始對話中屬於該使用者的最近 100 句話
let rawChatItems = [];
try {
  rawChatItems = $('取得原始對話').all();
} catch (e) {
  rawChatItems = [];
}

const userRecentMsgs = rawChatItems
  .map(item => item.json)
  .filter(item => item.userId === targetUserId)
  .slice(-100)
  .map(item => item.message)
  .join('\n');

return [{
  json: {
    targetUserId: targetUserId,
    userMessage: userMessage,
    userRecentHistory: userRecentMsgs || userMessage
  }
}];

const TARGET_GROUP_ID = 'C053946dc8a2d171370d71b040f006f8c';

const chatItems = $('Get row(s) in sheet').all();
if (!chatItems || !chatItems.length) throw new Error('Sheet 沒有資料');

const memberMap = {
  "黃元威": "U347ad9dd7ba9affc4c9ccab7335df20e",
  "蔡佳樺Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "蔡佳樺 Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "佳樺Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "黃鈞煜": "Ud303b043ce776a7b734ff950f91c6612"
};

// 容錯清洗姓名（去除冒號、全半形空格、Tab 鍵）
function normalizeName(str) {
  return String(str || '')
    .replace(/[:：\s\t\u00A0\u3000]/g, '')
    .toLowerCase()
    .trim();
}

function getUserId(speakerName) {
  if (!speakerName) return null;
  const target = normalizeName(speakerName);
  for (const [key, val] of Object.entries(memberMap)) {
    if (normalizeName(key) === target) return val;
  }
  return null;
}

const dateRegex = /^\d{4}[\.\/-]\d{2}[\.\/-]\d{2}/;
// 強化正則：自動相容 [時間] [發言者] [對話] 或帶有冒號的分隔
const lineRegex = /^(\d{1,2}:\d{2}(?::\d{2})?)[\s\t\u00A0\u3000]+([^\s\t\u00A0\u3000:：]+)[:：\s\t\u00A0\u3000]+(.*)$/;

const parsedMessages = [];
const rawSpeakersFound = new Set();
let currentDate = '';

for (const item of chatItems) {
  const rowObj = item?.json || {};

  const validEntries = Object.entries(rowObj).filter(([key, val]) => {
    if (val == null || val === '') return false;
    if (/^(row_number|row_id|id|index|_row)$/i.test(key)) return false;
    return true;
  });

  if (!validEntries.length) continue;
  const cleanLine = String(validEntries[0][1] || '').replace(/\r$/, '').trim();
  if (!cleanLine) continue;

  if (dateRegex.test(cleanLine)) {
    currentDate = cleanLine.split(' ')[0];
    continue;
  }

  const m = cleanLine.match(lineRegex);
  if (m) {
    const [, time, speaker, message] = m;
    rawSpeakersFound.add(speaker);
    const userId = getUserId(speaker);

    if (!userId) continue;
    if (!message || message === '已收回訊息' || ['貼圖', '圖片', '檔案', '語音訊息'].includes(message)) continue;
    if (message.startsWith('http://') || message.startsWith('https://')) continue;

    parsedMessages.push({
      date: currentDate,
      time,
      speaker,
      userId,
      message,
      groupId: TARGET_GROUP_ID
    });
  } else if (parsedMessages.length > 0) {
    if (!/^\d+$/.test(cleanLine)) {
      const last = parsedMessages[parsedMessages.length - 1];
      last.message += '\n' + cleanLine;
    }
  }
}

const enriched = parsedMessages.map(msg => ({
  json: {
    date: msg.date,
    time: msg.time,
    speaker: msg.speaker,
    message: msg.message,
    userId: msg.userId,
    groupId: TARGET_GROUP_ID,
    displayName: msg.speaker
  }
}));

const debugCount = {};
for (const msg of parsedMessages) {
  debugCount[msg.speaker] = (debugCount[msg.speaker] || 0) + 1;
}

enriched.push({
  json: {
    _debug: true,
    totalRowsParsed: chatItems.length,
    speakersDetectedInSheet: [...rawSpeakersFound],
    speakerMessageCounts: debugCount
  }
});

return enriched;

const items = $input.all();
const uniqueUsers = new Map();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  if (row._debug || !row.userId) continue;

  if (!uniqueUsers.has(row.userId)) {
    uniqueUsers.set(row.userId, {
      displayName: row.displayName || row.speaker || '',
      itemIndex: i
    });
  }
}

return [...uniqueUsers.entries()].map(([userId, info]) => ({
  json: { userId, displayName: info.displayName },
  pairedItem: { item: info.itemIndex }
}));

// 從「解析並對照 userId」的完整輸出中，篩出目前這個 userId 的所有發言
const targetUserId = $json.userId;
const targetDisplayName = $json.displayName;
const allMessages = $('解析並對照 userId').all();

const userMessages = allMessages
  .filter(item => item.json.userId === targetUserId)
  .map(item => item.json.message)
  .filter(Boolean);

// 單一使用者訊息量過大時，取最近 300 則做代表（可依需求調整）
const sampled = userMessages.slice(-1000);

const chatHistoryText = sampled
  .map(msg => `${targetDisplayName}: ${msg}`)
  .join('\n---\n') || '無發言紀錄';

return [{
  json: {
    targetUserId,
    targetDisplayName,
    chatHistory: chatHistoryText,
    messageCount: sampled.length
  }
}];

// 1. 取得 Gemini 辨識結果
const output = Array.isArray($json) ? $json[0] : $json;

// 2. 多層級相容路徑提取文字資訊
let description = 
  output.candidates?.[0]?.content?.parts?.[0]?.text || 
  output.text || 
  output.content?.parts?.[0]?.text || 
  $json.message ||
  $json.userMessage ||
  '';

description = description.trim();
if (!description) {
  description = '（圖片描述取得失敗）';
}

// 3. 提取 Token 消耗數據
const usage = output.usageMetadata || {};
const details = usage.promptTokensDetails || [];

const imgTokens = details.find(d => d.modality === 'IMAGE')?.tokenCount || 0;
const textTokens = details.find(d => d.modality === 'TEXT')?.tokenCount || 0;
const totalTokens = usage.totalTokenCount || 0;

// 4. 拉回原始 LINE 觸發 event 資料
const origin = $('Parse LINE Event').first().json;

// 5. 組裝單一輸出項目（防止產生空白 Row）
return [{
  json: {
    replyToken: origin.replyToken,
    groupId: origin.groupId || '',
    userId: origin.userId || '',
    message: description,       // 供 DataTable 寫入與 LINE 回覆使用
    userMessage: description,   // 備用相容欄位
    timestamp: origin.timestamp || Date.now(),
    tokenUsage: {
      imageTokens: imgTokens,
      promptTokens: textTokens,
      totalTokens: totalTokens
    }
  }
}];

