parameters.jsCode:
const origin = $('Parse LINE Event').first().json;
const cleanName = str => String(str || '').replace(/^models\//i, '').replace(/^gemini-?/i, '').trim().toLowerCase();

// 版本號解析函式（提取第一個小數或整數進行數字排序）
function getVersionScore(str) {
  const match = String(str).match(/(\d+(?:\.\d+)?)/);
  return match ? parseFloat(match[1]) : 0;
}

function getBadgeColor(wfName) {
  const lower = String(wfName).toLowerCase();
  if (lower.includes('主要') || lower === 'main') return '#1DB446';      // 綠色
  if (lower.includes('備用') || lower === 'alternate') return '#0288D1'; // 藍色
  if (lower.includes('kscpb')) return '#7B1FA2';                          // 紫色
  return '#FF8F00';                                                       // 橘色
}

// 1. 讀取 Data Table 當前所有 WORKFLOW 設定
const activeConfigs = [];
const activeModelSet = new Set();

try {
  let configRows = [];
  try {
    configRows = $('取得模型1').all();
  } catch(e1) {
    try {
      configRows = $('取得模型').all();
    } catch(e2) {
      try { configRows = $('讀取模型設定').all(); } catch(e3) {}
    }
  }

  for (const row of configRows) {
    const wf = String(row.json?.workflow || row.json?.WORKFLOW || row.json?.key || '').trim();
    const rawVal = String(row.json?.value || '').trim();
    const cVal = cleanName(rawVal);
    if (wf && rawVal) {
      activeConfigs.push({
        workflow: wf,
        rawModel: rawVal,
        displayModel: rawVal.replace(/^models\//i, '').replace(/^gemini-?/i, '')
      });
      activeModelSet.add(cVal);
    }
  }
} catch (e) {}

// 2. 抓取 Gemini 模型（排除 latest，保留 generateContent 基礎過濾）
let geminiModels = [];
try {
  let geminiRaw = [];
  try { geminiRaw = $('列出API_Gemini').first()?.json?.models || []; } catch(e) {}
  if (!geminiRaw.length) {
    try { geminiRaw = $('列出API').first()?.json?.models || []; } catch(e) {}
  }

  geminiModels = geminiRaw
    .filter(m => (m.supportedGenerationMethods || []).includes('generateContent'))
    .filter(m => !m.name.toLowerCase().includes('latest')) // 強制排除 latest
    .map(m => {
      const fullId = m.name;
      const cleanId = fullId.replace(/^models\//i, '');
      const lower = cleanId.toLowerCase();

      let groupKey = 'gemini_other';
      let groupLabel = 'Gemini 其他模型';

      if (lower.includes('lite')) {
        groupKey = 'gemini_lite';
        groupLabel = 'Gemini Lite 系列';
      } else if (lower.includes('flash')) {
        groupKey = 'gemini_flash';
        groupLabel = 'Gemini Flash 系列';
      } else if (lower.includes('pro')) {
        groupKey = 'gemini_pro';
        groupLabel = 'Gemini Pro 系列';
      }

      return {
        provider: 'Gemini',
        fullId: fullId,
        cleanId: cleanId,
        normalized: cleanName(cleanId),
        shortDisplay: cleanId.replace(/^gemini-?/i, ''),
        versionScore: getVersionScore(cleanId),
        groupKey: groupKey,
        groupLabel: groupLabel
      };
    });
} catch (e) {}

// 3. 抓取 Groq 模型（排除 latest）
let groqModels = [];
try {
  let groqRaw = [];
  try { groqRaw = $('列出API_Groq').first()?.json?.data || []; } catch(e) {}

  groqModels = groqRaw
    .filter(m => !m.id.toLowerCase().includes('latest')) // 強制排除 latest
    .map(m => {
      const fullId = m.id;
      return {
        provider: 'Groq',
        fullId: fullId,
        cleanId: fullId,
        normalized: cleanName(fullId),
        shortDisplay: fullId,
        versionScore: getVersionScore(fullId),
        groupKey: 'groq_models',
        groupLabel: 'Groq 高速系列'
      };
    });
} catch (e) {}

// 4. 列出【所有模型】（含使用中），並依【版本號從高到低】排序
const availableModels = [...geminiModels, ...groqModels]
  .sort((a, b) => b.versionScore - a.versionScore); // 版本號大排前面

// 5. 組裝【第一分頁】：當前套用 WORKFLOW 卡片
let firstBubble = null;
if (activeConfigs.length > 0) {
  const activeRows = [];
  activeConfigs.forEach((cfg, idx) => {
    if (idx > 0) activeRows.push({ type: 'separator', margin: 'sm' });
    activeRows.push({
      type: 'box',
      layout: 'horizontal',
      alignItems: 'center',
      paddingAll: '10px',
      backgroundColor: '#F8F9FA',
      cornerRadius: 'md',
      contents: [
        {
          type: 'box',
          layout: 'vertical',
          backgroundColor: getBadgeColor(cfg.workflow),
          cornerRadius: 'sm',
          paddingAll: '4px',
          flex: 0,
          contents: [
            { type: 'text', text: cfg.workflow.toUpperCase(), size: 'xs', color: '#FFFFFF', weight: 'bold' }
          ]
        },
        {
          type: 'text',
          text: cfg.displayModel,
          size: 'sm',
          weight: 'bold',
          color: '#333333',
          wrap: true,
          margin: 'md',
          flex: 1
        }
      ]
    });
  });

  firstBubble = {
    type: 'bubble',
    size: 'mega',
    header: {
      type: 'box',
      layout: 'vertical',
      backgroundColor: '#333333',
      paddingAll: '12px',
      contents: [
        { type: 'text', text: '⚡ 使用中 WORKFLOW 配置', weight: 'bold', size: 'md', color: '#ffffff' }
      ]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'sm',
      paddingAll: '12px',
      contents: activeRows
    }
  };
}

// 6. 組裝【可選模型卡片】
const groupOrder = [
  { key: 'gemini_lite', label: 'Gemini Lite 系列' },
  { key: 'gemini_flash', label: 'Gemini Flash 系列' },
  { key: 'gemini_pro', label: 'Gemini Pro 系列' },
  { key: 'gemini_other', label: 'Gemini 其他模型' },
  { key: 'groq_models', label: 'Groq 高速系列' }
];

const groups = new Map();
for (const m of availableModels) {
  if (!groups.has(m.groupKey)) {
    groups.set(m.groupKey, { label: m.groupLabel, models: [] });
  }
  groups.get(m.groupKey).models.push(m);
}

function buildModelRow(m) {
  const isActive = activeModelSet.has(m.normalized);
  const displayText = isActive ? `${m.shortDisplay} (使用中)` : m.shortDisplay;

  return {
    type: 'box',
    layout: 'horizontal',
    alignItems: 'center',
    spacing: 'xs',
    action: { type: 'message', label: m.shortDisplay, text: `/testmodel ${m.cleanId}` },
    paddingAll: '8px',
    backgroundColor: isActive ? '#E8F5E9' : '#F5F5F5', // 使用中的模型呈現淺綠底色
    cornerRadius: 'md',
    contents: [
      {
        type: 'text',
        text: displayText,
        size: 'sm',
        wrap: true,
        color: isActive ? '#2E7D32' : '#333333',
        weight: 'bold',
        flex: 1
      }
    ]
  };
}

const itemLimitPerBubble = 8;
const catalogBubbles = [];

for (const rule of groupOrder) {
  const group = groups.get(rule.key);
  if (!group || group.models.length === 0) continue;

  const subChunks = [];
  for (let i = 0; i < group.models.length; i += itemLimitPerBubble) {
    subChunks.push(group.models.slice(i, i + itemLimitPerBubble));
  }

  subChunks.forEach((chunk, idx) => {
    const title = subChunks.length > 1
      ? `${group.label}（${idx + 1}/${subChunks.length}）`
      : group.label;

    const rows = [];
    chunk.forEach((m, i) => {
      if (i > 0) rows.push({ type: 'separator', margin: 'sm' });
      rows.push(buildModelRow(m));
    });

    const isGroq = chunk[0]?.provider === 'Groq';

    catalogBubbles.push({
      type: 'bubble',
      size: 'mega',
      header: {
        type: 'box',
        layout: 'vertical',
        contents: [
          { type: 'text', text: title, weight: 'bold', size: 'md', color: '#ffffff' }
        ],
        backgroundColor: isGroq ? '#F55036' : '#1DB446',
        paddingAll: '12px'
      },
      body: {
        type: 'box',
        layout: 'vertical',
        spacing: 'sm',
        paddingAll: '12px',
        contents: rows
      }
    });
  });
}

// 7. 彙整所有 Bubbles
const allBubbles = [];
if (firstBubble) allBubbles.push(firstBubble);
allBubbles.push(...catalogBubbles);

const limitedBubbles = allBubbles.slice(0, 12);

const flexMessage = {
  type: 'flex',
  altText: `WORKFLOW 配置與可選模型清單`,
  contents: limitedBubbles.length > 1
    ? { type: 'carousel', contents: limitedBubbles }
    : limitedBubbles[0]
};

return [{
  json: {
    replyToken: origin.replyToken,
    payload: JSON.stringify({
      replyToken: origin.replyToken,
      messages: [flexMessage]
    })
  }
}];

const origin = $('Parse LINE Event').first().json;
const targetModel = origin.targetModel || 'gemini-2.5-flash';
const modelClean = targetModel.replace(/^models\//, '');
const isError = $json.error !== undefined;

// 1. 動態讀取 Data Table 中所有的配置項目 (自動抓取 key 與 workflow 名稱)
let configRows = [];
try { configRows = $('取得模型').all(); } catch(e) {
  try { configRows = $('讀取模型設定').all(); } catch(e2) {}
}

// 2. 動態生成按鈕清單
const buttons = configRows.map((row, idx) => {
  const key = String(row.json?.key || '').trim();
  const wfLabel = String(row.json?.workflow || row.json?.WORKFLOW || key).trim();

  return {
    type: 'button',
    style: idx === 0 ? 'primary' : 'secondary',
    color: idx === 0 ? '#1DB446' : undefined,
    height: 'sm',
    action: {
      type: 'message',
      label: wfLabel || key,
      text: `/setmodel ${key} ${modelClean}`
    }
  };
});

// 若資料庫暫時讀不到，提供基礎保底按鈕
if (buttons.length === 0) {
  buttons.push(
    {
      type: 'button',
      style: 'primary',
      color: '#1DB446',
      height: 'sm',
      action: { type: 'message', label: '設為主要', text: `/setmodel main ${modelClean}` }
    },
    {
      type: 'button',
      style: 'secondary',
      height: 'sm',
      action: { type: 'message', label: '設為備用', text: `/setmodel alternate ${modelClean}` }
    }
  );
}

// 3. 自動將按鈕「兩兩一組」排列，確保 LINE Flex Message 介面美觀不跑版
const buttonRows = [];
for (let i = 0; i < buttons.length; i += 2) {
  const pair = buttons.slice(i, i + 2);
  buttonRows.push({
    type: 'box',
    layout: 'horizontal',
    spacing: 'xs',
    contents: pair
  });
}

let flexMessage;

if (isError) {
  const errCode = $json.error?.httpCode || $json.statusCode || '未知';
  const errMsg = $json.error?.message || $json.message || '無詳細訊息';

  flexMessage = {
    type: 'flex',
    altText: `❌ ${modelClean} 測試失敗`,
    contents: {
      type: 'bubble',
      size: 'mega',
      header: {
        type: 'box',
        layout: 'vertical',
        backgroundColor: '#FF4B4B',
        paddingAll: '16px',
        contents: [
          { type: 'text', text: 'TEST FAILED', color: '#E0E0E0', size: 'xs', weight: 'bold' },
          { type: 'text', text: `❌ ${modelClean} 測試失敗`, color: '#FFFFFF', size: 'md', weight: 'bold', margin: 'xs' }
        ]
      },
      body: {
        type: 'box',
        layout: 'vertical',
        spacing: 'sm',
        contents: [
          { type: 'text', text: `狀態碼：${errCode}`, size: 'xs', color: '#888888' },
          { type: 'text', text: errMsg, size: 'sm', color: '#333333', wrap: true }
        ]
      },
      footer: {
        type: 'box',
        layout: 'vertical',
        contents: [
          {
            type: 'button',
            style: 'secondary',
            height: 'sm',
            action: { type: 'message', label: '重新選擇模型', text: '/models' }
          }
        ]
      }
    }
  };
} else {
  const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || $json.text || '(無回應內容)';

  flexMessage = {
    type: 'flex',
    altText: `✅ ${modelClean} 測試成功！`,
    contents: {
      type: 'bubble',
      size: 'mega',
      header: {
        type: 'box',
        layout: 'vertical',
        backgroundColor: '#1DB446',
        paddingAll: '16px',
        contents: [
          { type: 'text', text: 'TEST SUCCESS', color: '#E0E0E0', size: 'xs', weight: 'bold' },
          { type: 'text', text: `✅ ${modelClean} 運作正常`, color: '#FFFFFF', size: 'md', weight: 'bold', margin: 'xs' }
        ]
      },
      body: {
        type: 'box',
        layout: 'vertical',
        spacing: 'md',
        contents: [
          {
            type: 'box',
            layout: 'vertical',
            backgroundColor: '#F8F9FA',
            paddingAll: '12px',
            cornerRadius: 'md',
            contents: [
              { type: 'text', text: 'AI 回應測試：', size: 'xs', color: '#888888' },
              { type: 'text', text: text, size: 'sm', color: '#333333', wrap: true }
            ]
          },
          { type: 'text', text: '請選擇欲套用此模型的 WORKFLOW：', size: 'xs', color: '#666666', wrap: true }
        ]
      },
      footer: {
        type: 'box',
        layout: 'vertical',
        spacing: 'xs',
        contents: buttonRows
      }
    }
  };
}

return [{
  json: {
    replyToken: origin.replyToken,
    flexPayload: JSON.stringify({
      replyToken: origin.replyToken,
      messages: [flexMessage]
    })
  }
}];

const origin = $('Parse LINE Event').first().json;

let targetKey = origin.targetKey || 'main';
const requested = (origin.newModel || '').replace(/^models\//, '');
const modelToSave = `models/${requested}`;

// 自動至 Data Table 比對真實的 KEY 名稱（消除大小寫不一致問題）
try {
  let configRows = [];
  try { configRows = $('取得模型').all(); } catch(e) {
