        { type: 'text', text: `已設定 [ ${targetKey} ] 🚀`, color: '#FFFFFF', size: 'lg', weight: 'bold', margin: 'xs' }
      ]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'md',
      contents: [
        {
          type: 'box',
          layout: 'vertical',
          backgroundColor: '#F8F9FA',
          paddingAll: '12px',
