const firstItem = $input.first()?.json || {};
const body = firstItem.body || firstItem;
const events = body?.events || [];

if (!events || events.length === 0) {
  return [{ json: { message: "Webhook verify ok" } }];
}

// ⚠️ 管理員 LINE User ID 設定（可填入一個或多個 User ID，或使用環境變數 $env.ADMIN_USER_ID）
const ADMIN_USER_IDS = [
  'Ud303b043ce776a7b734ff950f91c6612', // 請將此處替換為你的 LINE User ID (例如: U1234567890abcdef...)
  $env.ADMIN_USER_ID   // 若 n8n 環境變數有設定 ADMIN_USER_ID 也會自動生效
].filter(Boolean);

const results = [];
const urlRegex = /(https?:\/\/[^\s]+)/i;

// 管理指令
const apiTestRegex = /^(測試api|測試gemini|\/checkapi)$/i;
const listModelsRegex = /^(列出模型|查詢模型|\/models)$/i;
const setModelRegex = /^\/setmodel\s+(.+)$/i;
const testModelRegex = /^\/testmodel\s+(\S+)$/i;

for (const event of events) {
  if (event.type === 'message') {
    const groupId = event.source?.groupId || event.source?.roomId || event.source?.userId;
    const userId = event.source?.userId;

    // 驗證當前發送者是否為管理員
    const isAdmin = ADMIN_USER_IDS.includes(userId);

    if (event.message?.type === 'text') {
      const text = (event.message.text || '').trim();

      // ----------------------------------------------------
      // 🔒 管理員專屬指令區 (非管理員會直接跳過此區塊)
      // ----------------------------------------------------
      if (isAdmin) {
        // 指令一：測試 API
        if (apiTestRegex.test(text)) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'api_test',
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令二：列出模型
        if (listModelsRegex.test(text)) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'list_models',
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令三：設定模型
        const setModelMatch = text.match(setModelRegex);
        if (setModelMatch) {
          const parts = setModelMatch[1].trim().split(/\s+/);
          const targetKey = parts.length >= 2 ? parts[0].toLowerCase() : 'main';
          const newModel = parts.length >= 2 ? parts[1].trim() : parts[0].trim();

          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'set_model',
              targetKey: targetKey,
              newModel: newModel,
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }

        // 指令四：測試模型
        const testModelMatch = text.match(testModelRegex);
        if (testModelMatch) {
          results.push({
            json: {
              replyToken: event.replyToken,
              groupId: groupId,
              userId: userId,
              userMessage: text,
              messageType: 'test_model',
              targetModel: testModelMatch[1].trim(),
              isTriggered: false,
              timestamp: event.timestamp
            }
          });
          continue;
        }
      }

      // ----------------------------------------------------
      // 💬 一般對話與網址解析區
      // ----------------------------------------------------
      const urlMatch = text.match(urlRegex);
      if (urlMatch) {
        results.push({
          json: {
            replyToken: event.replyToken,
            groupId: groupId,
            userId: userId,
            userMessage: text,
            url: urlMatch[1],
            messageType: 'url',
            isTriggered: false,
            timestamp: event.timestamp
          }
        });
      } else {
        const isSummaryReq = /統整|摘要|總結/i.test(text);
        const triggerRegex = /[@＠]bot|我要吃香腸|幽默大師|講一個笑話|吃啥|作詩|出來面對/i;

        results.push({
          json: {
            replyToken: event.replyToken,
            groupId: groupId,
            userId: userId,
            userMessage: text,
            messageType: 'text',
            isTriggered: triggerRegex.test(text) || isSummaryReq,
            isSummaryReq: isSummaryReq,
            timestamp: event.timestamp
          }
        });
      }

    } else if (event.message?.type === 'image') {
      results.push({
        json: {
          replyToken: event.replyToken,
          groupId: groupId,
          userId: userId,
          messageId: event.message.id,
          messageType: 'image',
          isTriggered: false,
          timestamp: event.timestamp
        }
      });
    }
  }
}

return results.length > 0 ? results : [{ json: { status: "ignored" } }];

// 1. 取得全體團員的人設對照表（相容新舊節點名稱）
let rawImportantItems = [];
try {
  rawImportantItems = $('取得全團員人格特質').all();
} catch (e) {
  try { rawImportantItems = $('Get row(s)1').all(); } catch (err) {}
}

const personaMap = new Map(); // userId -> { id, name, info }

for (const item of rawImportantItems) {
  const userId = item.json?.userId;
  const name = item.json?.displayName || item.json?.message; 
  const info = item.json?.info;
  const id = item.json?.id;

  if (!userId || userId === 'Null' || !name || name === 'Null' || String(name).trim() === '') continue;

  const cleanInfo = (!info || info === 'Null') ? '' : String(info).trim();

  // 保留該 userId 最新的一筆紀錄
  const existing = personaMap.get(userId);
  if (!existing || id > existing.id) {
    personaMap.set(userId, { id, name: String(name).trim(), info: cleanInfo });
  }
}

const importantLines = [];
for (const [userId, data] of personaMap.entries()) {
  const infoPart = data.info ? ` [特徵/人設/暱稱: ${data.info}]` : '';
  importantLines.push(`- ${data.name}${infoPart} (ID: ${userId})`);
}
const importantHistoryText = importantLines.join('\n') || '無成員人設資料';

// 2. 取得歷史對話紀錄
let rawChatItems = [];
try {
  rawChatItems = $('Get row(s)').all();
} catch (e) {
  rawChatItems = $input.all();
}

const seenChatIds = new Set();
const chatMessages = [];

for (const item of rawChatItems) {
  const id = item.json?.id;
  if (id && seenChatIds.has(id)) continue;
  if (id) seenChatIds.add(id);

  const userId = item.json?.userId || '未知成員';
  const msg = item.json?.message || '';

  // 透過 userId 比對全團員人設表
  const persona = personaMap.get(userId);

  let displayName = userId;
  if (persona) {
    displayName = persona.name;
  } else if (userId !== '未知成員') {
    displayName = `成員(${userId.slice(-4)})`;
  }

  chatMessages.push(`[發言者: ${displayName}] (ID: ${userId})\n${msg}`);
}

const chatHistoryText = chatMessages.reverse().join('\n---\n') || '無一般歷史紀錄';

// 3. 取得當前發問者資訊
let lineEvent = {};
try {
  lineEvent = $('Parse LINE Event').item.json;
} catch (e) {
  try { lineEvent = $('LINE Webhook').item.json.body.events[0]; } catch (err) {}
}

const userLatestMsg = lineEvent.userMessage || lineEvent.message?.text || '';
const groupId = lineEvent.groupId || lineEvent.source?.groupId || '';
const currentUserId = lineEvent.userId || lineEvent.source?.userId || '';

const currentPersona = personaMap.get(currentUserId);
const currentUserName = currentPersona ? currentPersona.name : currentUserId;

// 4. 輸出 Prompt
return [{
  json: {
    prompt: `【當前發問者】：${currentUserName} (ID: ${currentUserId})
【使用者最新指令/提問】：${userLatestMsg}

【群組最近對話紀錄】：
${chatHistoryText}

【群組成員稱號與人設特徵對照】：
${importantHistoryText}

-------------------
【稱呼與人名強制規範】：
1. 名字 100% 完全精確（零錯字原則）：稱呼成員時，如果使用 displayName，必須 100% 完全複製上方「對照表」中的字形，嚴禁自作聰明替換成同音字、同音異體字或簡體字。
2. 靈活使用群組暱稱：亦可直接使用 info 欄位內提到的常見暱稱（如：吉爺、C祖），讓對話自然風趣。
3. 發言歸屬精準：標註的發言者名稱即為該句話的真正發言人，請精準辨識「誰說了什麼話」，切勿張冠李戴。`
  }
}];

const isError = $json.error !== undefined;
const origin = $('Parse LINE Event').item.json;

if (isError) {
  return [{
    json: {
      pageText: '（此網址無法正常抓取內容，可能被網站阻擋或連線逾時）',
      fetchFailed: true,
      url: origin.url,
      replyToken: origin.replyToken,
      groupId: origin.groupId,
      userId: origin.userId,
      userMessage: origin.userMessage,
      timestamp: origin.timestamp
    }
  }];
}

const html = $json.data || $json.body || String($json) || '';
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 4000);

return [{
  json: {
    pageText: text,
    fetchFailed: false,
    url: origin.url,
    replyToken: origin.replyToken,
    groupId: origin.groupId,
    userId: origin.userId,
    userMessage: origin.userMessage,
