  }
}];

const origin = $('Parse LINE Event').item.json;
const analysis = $json.output || '（連結分析取得失敗）';

return [{
  json: {
    replyToken: origin.replyToken,
    groupId: origin.groupId,
    userId: origin.userId,
    userMessage: `[連結] ${analysis}`,
    timestamp: origin.timestamp
  }
}];

let lineEvent = {};
try {
  lineEvent = $('Parse LINE Event').item.json;
} catch (e) {
  try { lineEvent = $('LINE Webhook').item.json.body.events[0]; } catch (err) {}
}

const userMessage = lineEvent.userMessage || lineEvent.message?.text || '';
const targetUserId = lineEvent.userId || lineEvent.source?.userId || '';

// 撈取原始對話中屬於該使用者的最近 100 句話
let rawChatItems = [];
try {
  rawChatItems = $('取得原始對話').all();
} catch (e) {
  rawChatItems = [];
}

const userRecentMsgs = rawChatItems
  .map(item => item.json)
  .filter(item => item.userId === targetUserId)
  .slice(-100)
  .map(item => item.message)
  .join('\n');

return [{
  json: {
    targetUserId: targetUserId,
    userMessage: userMessage,
    userRecentHistory: userRecentMsgs || userMessage
  }
}];

const TARGET_GROUP_ID = 'C053946dc8a2d171370d71b040f006f8c';

const chatItems = $('Get row(s) in sheet').all();
if (!chatItems || !chatItems.length) throw new Error('Sheet 沒有資料');

const memberMap = {
  "黃元威": "U347ad9dd7ba9affc4c9ccab7335df20e",
  "蔡佳樺Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "蔡佳樺 Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "佳樺Alisa": "U6930276b69cdc18847f91e4a1390cf1d",
  "黃鈞煜": "Ud303b043ce776a7b734ff950f91c6612"
};

// 容錯清洗姓名（去除冒號、全半形空格、Tab 鍵）
function normalizeName(str) {
  return String(str || '')
    .replace(/[:：\s\t\u00A0\u3000]/g, '')
    .toLowerCase()
    .trim();
}

function getUserId(speakerName) {
  if (!speakerName) return null;
  const target = normalizeName(speakerName);
  for (const [key, val] of Object.entries(memberMap)) {
    if (normalizeName(key) === target) return val;
  }
  return null;
}

const dateRegex = /^\d{4}[\.\/-]\d{2}[\.\/-]\d{2}/;
// 強化正則：自動相容 [時間] [發言者] [對話] 或帶有冒號的分隔
const lineRegex = /^(\d{1,2}:\d{2}(?::\d{2})?)[\s\t\u00A0\u3000]+([^\s\t\u00A0\u3000:：]+)[:：\s\t\u00A0\u3000]+(.*)$/;

const parsedMessages = [];
const rawSpeakersFound = new Set();
let currentDate = '';

for (const item of chatItems) {
  const rowObj = item?.json || {};

  const validEntries = Object.entries(rowObj).filter(([key, val]) => {
    if (val == null || val === '') return false;
    if (/^(row_number|row_id|id|index|_row)$/i.test(key)) return false;
    return true;
  });

  if (!validEntries.length) continue;
  const cleanLine = String(validEntries[0][1] || '').replace(/\r$/, '').trim();
  if (!cleanLine) continue;

  if (dateRegex.test(cleanLine)) {
    currentDate = cleanLine.split(' ')[0];
    continue;
  }

  const m = cleanLine.match(lineRegex);
  if (m) {
    const [, time, speaker, message] = m;
    rawSpeakersFound.add(speaker);
    const userId = getUserId(speaker);

    if (!userId) continue;
    if (!message || message === '已收回訊息' || ['貼圖', '圖片', '檔案', '語音訊息'].includes(message)) continue;
    if (message.startsWith('http://') || message.startsWith('https://')) continue;

    parsedMessages.push({
      date: currentDate,
      time,
      speaker,
      userId,
      message,
      groupId: TARGET_GROUP_ID
    });
  } else if (parsedMessages.length > 0) {
    if (!/^\d+$/.test(cleanLine)) {
      const last = parsedMessages[parsedMessages.length - 1];
      last.message += '\n' + cleanLine;
    }
  }
}

const enriched = parsedMessages.map(msg => ({
  json: {
    date: msg.date,
    time: msg.time,
    speaker: msg.speaker,
    message: msg.message,
    userId: msg.userId,
    groupId: TARGET_GROUP_ID,
    displayName: msg.speaker
  }
}));

const debugCount = {};
for (const msg of parsedMessages) {
  debugCount[msg.speaker] = (debugCount[msg.speaker] || 0) + 1;
}

enriched.push({
  json: {
    _debug: true,
    totalRowsParsed: chatItems.length,
    speakersDetectedInSheet: [...rawSpeakersFound],
    speakerMessageCounts: debugCount
  }
});

return enriched;

const items = $input.all();
const uniqueUsers = new Map();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  if (row._debug || !row.userId) continue;

  if (!uniqueUsers.has(row.userId)) {
    uniqueUsers.set(row.userId, {
      displayName: row.displayName || row.speaker || '',
      itemIndex: i
    });
  }
}

return [...uniqueUsers.entries()].map(([userId, info]) => ({
  json: { userId, displayName: info.displayName },
  pairedItem: { item: info.itemIndex }
}));

// 從「解析並對照 userId」的完整輸出中，篩出目前這個 userId 的所有發言
const targetUserId = $json.userId;
const targetDisplayName = $json.displayName;
const allMessages = $('解析並對照 userId').all();

const userMessages = allMessages
  .filter(item => item.json.userId === targetUserId)
  .map(item => item.json.message)
  .filter(Boolean);

// 單一使用者訊息量過大時，取最近 300 則做代表（可依需求調整）
const sampled = userMessages.slice(-1000);

const chatHistoryText = sampled
  .map(msg => `${targetDisplayName}: ${msg}`)
  .join('\n---\n') || '無發言紀錄';

return [{
  json: {
    targetUserId,
    targetDisplayName,
    chatHistory: chatHistoryText,
    messageCount: sampled.length
  }
}];

// 1. 取得 Gemini 辨識結果
const output = Array.isArray($json) ? $json[0] : $json;

// 2. 多層級相容路徑提取文字資訊
let description = 
  output.candidates?.[0]?.content?.parts?.[0]?.text || 
  output.text || 
  output.content?.parts?.[0]?.text || 
  $json.message ||
  $json.userMessage ||
