parameters.jsCode:
// 從上一個節點「解析並對照 userId」獲取所有資料
const items = $input.all();
const userGroupMap = new Map();

for (const item of items) {
  const row = item.json || {};

  // 自動跳過 Debug 診斷資料與沒有 userId 的項目
  if (row._debug || !row.userId) continue;

  const { userId, displayName, message, date, time } = row;

  if (!userGroupMap.has(userId)) {
    userGroupMap.set(userId, {
      userId,
      displayName: displayName || row.speaker || '',
      rawMessages: [],
      formattedMessages: []
    });
  }

  const userObj = userGroupMap.get(userId);
  if (message) {
    userObj.rawMessages.push(message);
    userObj.formattedMessages.push(`[${date || ''} ${time || ''}] ${message}`);
  }
}

// 轉為 n8n 標準格式輸出（每一個成員獨立成一個 Item，方便後續跑 Loop 或 AI 分析）
return [...userGroupMap.values()].map(userData => ({
  json: {
    userId: userData.userId,
    displayName: userData.displayName,
    messageCount: userData.rawMessages.length,
    // 【適合送給 AI 人設分析】打包成附帶時間戳記的個人對話大區塊
    fullChatHistory: userData.formattedMessages.join('\n'),
    // 保留純文字對話陣列
    messages: userData.rawMessages
  }
}));

